settings.custom_css:
.header__icons .g-translate-selector{
  display: none;
}.header__icons .g-translate-selector .gt_switcher {
  position: relative;
  width: auto;
  overflow: visible;
  padding-inline: 0.6rem;
}
.header__icons .g-translate-selector .gt_switcher .gt_selected a {
  color: inherit;
  width: auto;
  padding: 0;
  font-size: 0;
  border: none;
}
.header__icons .g-translate-selector .gt_switcher .gt_selected a :after {
  display: none !important;
}
.header__icons .g-translate-selector .gt_switcher .gt_selected a img {
  display: block;
  width: 1.8rem;
  height: auto;
  opacity: 1;
}
.header__icons .g-translate-selector .gt_switcher .gt_option {
  position: absolute;
  right: 0;
  width: 20rem;
  box-shadow: 0 0 1.0625rem -0.3125rem rgba(0, 0, 0, 0.15);
  border-radius: 0.4375rem;
  margin-top: 1rem;
}
.header__icons .g-translate-selector .gt_switcher .gt_option a {
  display: flex;
  align-items: center;
  padding: 1.2rem 1.6rem;
  border-top: 1px solid #eee;
  font-size: 1.4rem;
}
.header__icons .g-translate-selector .gt_switcher .gt_option a img {
  width: 1.8rem;
  height: 1.8rem;
  margin-right: 0.8rem;
}
